<?php
declare(strict_types=1);
require __DIR__ . '/../api/auth.php';
$user = require_auth();
$csrf = csrf_token();
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mahameru — Visit</title><link rel="stylesheet" href="assets/app.css"></head><body><main class="container"><header class="topbar"><div><div class="brand">MAHAMERU</div><div class="muted">Visit & Check-In</div></div><a class="button" href="sales.php">Sales</a></header><section class="card"><h2>Visit</h2><p class="muted">Check-In dan Check-Out divalidasi backend: outlet assignment, GPS radius, jam operasional, foto, durasi minimum, dan active visit.</p><div id="active" class="muted">Memeriksa kunjungan...</div><label>Outlet ID<input id="outlet_id" type="number" min="1" required></label><label>Foto Outlet (wajib)<input id="photo" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" required></label><button class="primary" id="checkin">Ambil Lokasi & Check-In</button><button class="button" id="checkout" hidden>Ambil Lokasi & Check-Out</button><pre id="result"></pre></section></main><script>const csrf=<?=json_encode($csrf)?>;const result=document.querySelector('#result'),activeEl=document.querySelector('#active'),checkout=document.querySelector('#checkout'),checkin=document.querySelector('#checkin');let activeVisit=null;async function refresh(){try{const r=await fetch('../api/visit.php?action=active',{credentials:'same-origin',headers:{Accept:'application/json'}});const d=await r.json();activeVisit=d.success?d.visit:null;if(activeVisit){activeEl.textContent='Visit ACTIVE: '+(activeVisit.outlet_name||activeVisit.outlet_code||activeVisit.outlet_id);document.querySelector('#outlet_id').disabled=true;document.querySelector('#photo').disabled=true;checkin.hidden=true;checkout.hidden=false;}else{activeEl.textContent='Tidak ada Visit ACTIVE.';document.querySelector('#outlet_id').disabled=false;document.querySelector('#photo').disabled=false;checkin.hidden=false;checkout.hidden=true;}}catch(e){activeEl.textContent='Gagal membaca status Visit.';}}function gps(){return new Promise((resolve,reject)=>{if(!navigator.geolocation)return reject(new Error('GPS tidak tersedia.'));navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,timeout:15000,maximumAge:0});});}checkin.onclick=async()=>{const outlet=Number(document.querySelector('#outlet_id').value),file=document.querySelector('#photo').files[0];if(!outlet||!file){result.textContent='Outlet dan foto wajib diisi.';return;}checkin.disabled=true;try{const up=new FormData();up.append('photo',file);const ur=await fetch('../api/visit_photo.php',{method:'POST',headers:{'X-CSRF-TOKEN':csrf},body:up,credentials:'same-origin'});const ud=await ur.json();if(!ud.success)throw new Error(ud.message||'Upload foto gagal');const p=await gps();const body=new URLSearchParams({action:'checkin',outlet_id:String(outlet),latitude:String(p.coords.latitude),longitude:String(p.coords.longitude),accuracy_meters:String(p.coords.accuracy),photo_path:ud.photo_path,mock_location_detected:'false'});const r=await fetch('../api/visit.php',{method:'POST',headers:{'X-CSRF-TOKEN':csrf,'Content-Type':'application/x-www-form-urlencoded'},body,credentials:'same-origin'});result.textContent=await r.text();await refresh();}catch(e){result.textContent='Check-In gagal: '+e.message;}finally{checkin.disabled=false;}};checkout.onclick=async()=>{checkout.disabled=true;try{const p=await gps();const body=new URLSearchParams({action:'checkout',latitude:String(p.coords.latitude),longitude:String(p.coords.longitude)});const r=await fetch('../api/visit.php',{method:'POST',headers:{'X-CSRF-TOKEN':csrf,'Content-Type':'application/x-www-form-urlencoded'},body,credentials:'same-origin'});result.textContent=await r.text();await refresh();}catch(e){result.textContent='Check-Out gagal: '+e.message;}finally{checkout.disabled=false;}};refresh();</script></body></html>
